import { Await } from "@kasperrt/smolter/preact";

export function Reviews({ reviews }: { reviews: Promise<string[]> }) {
  return (
    <Await resolve={reviews}
      fallback={<p role="status">Loading reviews…</p>}
      errorElement={<p>Reviews are unavailable.</p>}>
      {(items) => <ul>{items.map((item) => <li key={item}>{item}</li>)}</ul>}
    </Await>
  );
}
